def simulate_final():
    prod_node = node_by_title(doc, "Plant 1912, Period 03: Products")
    products_info = {}
    for row_idx, row in table_rows(prod_node):
        p = row['product']
        products_info[p] = {
            "kg_per_unit": float(row['kg per unit']),
            "opening_stock": int(row['opening stock'])
        }

    ledger_node = node_by_title(doc, "Plant 1912, Period 03: Daily ledger")
    daily_data = collections.defaultdict(lambda: collections.defaultdict(lambda: {"prod": 0, "ord": 0}))
    for row_idx, row in table_rows(ledger_node):
        day = int(row['day'])
        p = row['product']
        daily_data[day][p]["prod"] = int(row['produced'])
        daily_data[day][p]["ord"] = int(row['ordered'])

    stock = {p: info["opening_stock"] for p, info in products_info.items()}
    queue = collections.deque() # (product, quantity, day_placed, order_id)
    order_id_counter = 0

    results = {}
    order_final_status = {} # (product, day_placed) -> shipped_in_full_on_day

    for day in range(29, 43):
        capacity = 34500 if day < 36 else 27600
        for p in products_info:
            stock[p] += daily_data[day][p]["prod"]

        for p in products_info:
            ord_qty = daily_data[day][p]["ord"]
            if ord_qty > 0:
                queue.append([p, ord_qty, day, order_id_counter])
                order_id_counter += 1

        unused_capacity = capacity
        shipped_today = collections.defaultdict(int)
        capacity_reached = False

        sorted_queue = sorted(list(queue), key=lambda x: (x[2], x[1], x[0]))
        queue = collections.deque(sorted_queue)

        new_queue = collections.deque()
        while queue:
            order = queue.popleft()
            p, qty, day_placed, oid = order

            can_ship_stock = stock[p]
            can_ship_cap = int(unused_capacity // products_info[p]["kg_per_unit"])

            shippable = min(qty, can_ship_stock, can_ship_cap)

            if shippable > 0:
                stock[p] -= shippable
                shipped_today[p] += shippable
                unused_capacity -= shippable * products_info[p]["kg_per_unit"]
                remaining_qty = qty - shippable
            else:
                remaining_qty = qty

            if shippable < qty and (stock[p] + shippable) > shippable and can_ship_cap == shippable:
                capacity_reached = True

            if remaining_qty > 0:
                new_queue.append([p, remaining_qty, day_placed, oid])
            else:
                if (p, day_placed) not in order_final_status:
                    order_final_status[(p, day_placed)] = day

        queue = new_queue
        results[day] = {
            "capacity_reached": capacity_reached,
            "products": {p: {"stock": stock[p]} for p in products_info}
        }

    return results, order_final_status

